/deep/.ivu-modal-body {
  height: 528px;
  overflow: auto;
}

.input-wrapper {
  display: flex;

  .ivu-btn {
    color: #1890FF;
  }

  .ivu-btn:focus {
    box-shadow: none;
  }

  +.picture-list {
    margin-top: 20px;
  }
}

.tips {
  font-size: 12px;
  color: #BBBBBB;
}

.picture-list {
  display: flex;
  flex-wrap: wrap;

  .item {
    position: relative;
    width: 64px;
    height: 64px;
    margin: 0 10px 10px 0;
  }

  .image {
    width: 100%;
    height: 100%;
    border-radius: 4px;
  }

  .ivu-icon-ios-close-circle {
    position: absolute;
    top: 0;
    right: 0;
    transform: translate(30%, -30%);
    cursor: pointer;
  }

  .ivu-icon-ios-add {
    border: 1px dashed #DDDDDD;
    border-radius: 4px;

    &:hover {
      border-color: #57a3f3;
    }
  }
}

.scan-code-upload {
  display: flex;

  .qrcode {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 200px;
    height: 200px;
    border: 1px solid #DDDDDD;
    border-radius: 4px;
  }

  .qrcode-wrapper {
    .tips {
      text-align: center;
      line-height: 28px;

      &.large {
        font-size: 14px;
        color: #333333;
      }
    }
  }

  .picture-wrapper {
    flex: 1;
    padding-left: 20px;

    .tips {
      font-size: 12px;
      color: #BBBBBB;
    }
  }
}

/deep/.upload-img-modal {
  .ivu-radio-wrapper {
    margin-right: 30px;
  }

  .ivu-radio {
    margin-right: 10px;
  }

  .ivu-input {
    padding-left: 15px;
    border-color: #DDDDDD;
  }

  .ivu-modal-footer {
    border-top: none;

    button + button {
      margin-left: 14px;
    }
  }
}
